#!/usr/bin/env bash
# Сторож страницы маски th2: она отдаётся наружу байт в байт, и выдать
# назначение имени не должна ничем. Исполняется шагом ci.yml и приманками
# test/mask-page-guard.test.sh — один и тот же файл, поэтому проверяется
# поведение сторожа, а не его копия.
#
#   bash .github/scripts/mask-page-guard.sh deploy/hosts/th2/cdn
#
# Образец — шаг «Страница маски ничего не выдаёт» репозитория
# MikeKharr/zpq-ai (ci.yml), перенесённый сюда вместе с маской (ADR
# 2026-10-05-2223, раздел «Индексация, блокировка, взлом, SEO»). Там первая
# редакция страницы несла комментарий со словами «маска», «:8444» и названием
# шага выкатки — то есть выдавала и назначение имени, и внутренний порт
# (блокирующие гейтов compliance и reviewer). Поэтому сторож, а не ревью.
#
# Что ловит:
#   1. HTML-комментарий — исходник страницы читает кто угодно из интернета, и
#      объяснения живут в Caddyfile, а не в отдаваемом файле;
#   2. слова, называющие назначение имени или внутренний порт;
#   3. отсутствие метки build-id — обратная сторона того же предмета: по ней
#      проверка выкатки отличает нашу страницу от чужого 200, и без метки она
#      краснела бы на проде;
#   4. robots.txt без `User-agent: *` и `Disallow: /` — требование владельца
#      2026-10-05 держится ДВУМЯ носителями, и этот — первый. Второй,
#      заголовок `X-Robots-Tag`, живёт в Caddyfile и проверяется отдельным
#      шагом по результату `caddy adapt`: grep по Caddyfile зеленел бы и на
#      заголовке, уехавшем в чужой блок.
#
# Чего сторож НЕ держит: что страница вообще отдаётся и что заголовок доехал
# до прода. Это живая проверка выкатки (PR A-2) и таблица ADR.
#
# Коды: 0 — чисто, 1 — находка, 2 — проверка не выполнилась.
set -euo pipefail

dir="${1:-}"
[ -n "$dir" ] || { echo "::error::нужен аргумент: каталог страницы маски"; exit 2; }
[ -d "$dir" ] || { echo "::error::нет каталога $dir — страницы маски нет, а блок cdn2.zpq.ai:8444 в Caddyfile на неё ссылается"; exit 2; }

files=$(find "$dir" -type f | sort)
[ -n "$files" ] || { echo "::error::каталог $dir пуст — страницы маски нет, а блок cdn2.zpq.ai:8444 в Caddyfile на неё ссылается"; exit 2; }
echo "проверяются файлы:"
printf '%s\n' "$files" | sed 's/^/  /'

found=0

# Слова — те же, что у th1, плюс 8443 и 8444: оба внутренних порта этой
# машины. Регистр не важен, кириллица и латиница вперемешку намеренно:
# «маск» ловит «маска», «маскировка», «маски».
# LC_ALL=C не ставится: образец должен совпадать и с кириллицей, а в C-локали
# -i по кириллице не работает.
while IFS= read -r f; do
  base=$(basename "$f")
  if grep -n -F '<!--' "$f"; then
    echo "::error::$f содержит HTML-комментарий: исходник этой страницы читает кто угодно из интернета, объяснения — в комментарии блока cdn2.zpq.ai:8444 в deploy/hosts/th2/Caddyfile, а не в отдаваемом файле"
    found=1
  fi
  # robots.txt исключён из запрета слов и исключён намеренно: в нём ровно две
  # строки, ни одного запретного слова в них нет и быть не может, а под общий
  # образец он попал бы словом `Disallow` — нет, но ясность дешевле.
  if [ "$base" != robots.txt ] && grep -n -iE 'маск|vpn|proxy|8443|8444|xray|reality|triplify' "$f"; then
    echo "::error::$f называет назначение имени, внутренний порт или провайдера: страница обязана выглядеть обычным хостом статики"
    found=1
  fi
done <<EOF
$files
EOF

page="$dir/index.html"
if [ ! -s "$page" ]; then
  echo "::error::нет $page — Caddy отдавал бы листинг каталога или 404 вместо страницы"
  found=1
else
  grep -q -F 'cdn2-zpq-ai-static' "$page" || {
    echo "::error::в $page нет метки cdn2-zpq-ai-static — проверка выкатки «маска отдаёт страницу» не сможет отличить нашу страницу от чужого 200"
    found=1; }
  # Имя на странице обязано быть своим: копия страницы th1 с именем
  # cdn.zpq.ai на th2 выглядела бы безупречно и называла бы ЧУЖОЕ имя на
  # адресе, где оно не живёт, — то есть ровно тот признак, от которого вся
  # маска и нужна.
  grep -q -F 'cdn2.zpq.ai' "$page" || {
    echo "::error::в $page нет имени cdn2.zpq.ai — страница маски th2 не называет имя, на котором стоит"
    found=1; }
  if grep -n -E '(^|[^0-9a-z.-])cdn\.zpq\.ai' "$page"; then
    echo "::error::в $page упомянуто имя маски ДРУГОГО хоста (cdn.zpq.ai) — страница скопирована с th1 и не поправлена"
    found=1
  fi
fi

robots="$dir/robots.txt"
if [ ! -s "$robots" ]; then
  echo "::error::нет $robots — имя маски открыто обходу роботов, а требование владельца 2026-10-05 его закрывает"
  found=1
else
  grep -qE '^[[:space:]]*Disallow:[[:space:]]*/[[:space:]]*$' "$robots" || {
    echo "::error::в $robots нет строки «Disallow: /» — имя маски открыто обходу роботов"
    found=1; }
  grep -qiE '^[[:space:]]*User-agent:[[:space:]]*\*[[:space:]]*$' "$robots" || {
    echo "::error::в $robots нет строки «User-agent: *» — Disallow без группы агентов не действует ни на кого"
    found=1; }
fi

if [ "$found" -ne 0 ]; then
  exit 1
fi
echo "ok: страница маски th2 ничего не выдаёт, метка на месте, robots.txt закрывает обход"
sed 's/^/  /' "$robots"
